# Turned (clockwise) -> upright, as content/crop.py upright_box - copied: a
# migration doesn't import code that may change after it.
_FROM_TURNED = {
    0: lambda u, v: (u, v),
    90: lambda u, v: (v, 1 - u),
    180: lambda u, v: (1 - u, 1 - v),
    270: lambda u, v: (1 - v, u),
}


def _upright(box, rotation):
    if not rotation:
        return box
    x, y, w, h = box
    corners = [_FROM_TURNED[rotation](x, y), _FROM_TURNED[rotation](x + w, y + h)]
    xs, ys = [c[0] for c in corners], [c[1] for c in corners]
    return min(xs), min(ys), max(xs) - min(xs), max(ys) - min(ys)


def frames_from_portraits(apps, schema_editor):
    """Every portrait crop is a face whose place is known (issue #480): it
    becomes that person's frame on that photo - on the photo as shown (a
    turned portrait mapped back). The same fact, already recorded - copied,
    not guessed. Someone with a portrait from a photo but not linked to it
    is linked, without a role: the portrait says they're on it. A frame
    already there is left alone."""
    Portrait = apps.get_model('content', 'Portrait')
    ContentPerson = apps.get_model('content', 'ContentPerson')
    for portrait in Portrait.objects.exclude(crop_x=None).exclude(crop_y=None).exclude(crop_w=None).exclude(crop_h=None):
        link, _created = ContentPerson.objects.get_or_create(content_id=portrait.content_id, person_id=portrait.person_id, defaults={'role': ''})
        if link.region_x is not None:
            continue
        box = _upright((portrait.crop_x, portrait.crop_y, portrait.crop_w, portrait.crop_h), portrait.rotation)
        link.region_x, link.region_y, link.region_w, link.region_h = (round(value, 4) for value in box)
        link.save(update_fields=['region_x', 'region_y', 'region_w', 'region_h'])


